{
  "websocket_guide": {
    "connection_url": "ws://localhost:3001/group-chat",
    "live_url": "ws://103.190.136.200:3000/group-chat",
    "steps": [
      {
        "step": 1,
        "action": "Connect to WebSocket",
        "url": "ws://localhost:3001/group-chat",
        "note": "Use Socket.IO client or browser WebSocket"
      },
      {
        "step": 2,
        "action": "Authenticate",
        "event": "authenticate",
        "payload": {
          "token": "{{auth_token}}"
        },
        "expected_response": {
          "event": "authenticated",
          "data": {
            "success": true,
            "userId": "user-uuid",
            "userName": "User Name"
          }
        }
      },
      {
        "step": 3,
        "action": "Join Group",
        "event": "joinGroup",
        "payload": {
          "groupId": "{{group_id}}"
        },
        "expected_response": {
          "event": "joinedGroup",
          "data": {
            "groupId": "group-uuid",
            "message": "Successfully joined group chat"
          }
        }
      },
      {
        "step": 4,
        "action": "Send Message",
        "event": "sendGroupMessage",
        "payload": {
          "groupId": "{{group_id}}",
          "content": "Hello group!",
          "messageType": "text",
          "metadata": {}
        },
        "expected_response": {
          "event": "groupMessageReceived",
          "data": {
            "messageId": "message-id",
            "senderId": "sender-uuid",
            "senderName": "Sender Name",
            "groupId": "group-uuid",
            "content": "Hello group!",
            "messageType": "text",
            "timestamp": "2023-10-01T12:00:00Z"
          }
        }
      }
    ],
    "available_events": {
      "client_to_server": [
        "authenticate",
        "joinGroup",
        "leaveGroup",
        "sendGroupMessage",
        "getGroupMessageHistory",
        "markGroupMessageAsRead",
        "groupTyping",
        "deleteGroupMessage",
        "editGroupMessage",
        "getGroupMembers"
      ],
      "server_to_client": [
        "authenticated",
        "authenticationError",
        "joinedGroup",
        "leftGroup",
        "userJoinedGroup",
        "userLeftGroup",
        "groupMessageReceived",
        "groupMessageHistory",
        "messagesMarkedAsRead",
        "userTypingInGroup",
        "groupMessageDeleted",
        "groupMessageEdited",
        "groupMembersList",
        "error"
      ]
    }
  }
}

{
  "websocket_message_templates": {
    "authentication": {
      "event": "authenticate",
      "data": {
        "token": "{{auth_token}}"
      }
    },
    "join_group": {
      "event": "joinGroup",
      "data": {
        "groupId": "{{group_id}}"
      }
    },
    "send_text_message": {
      "event": "sendGroupMessage",
      "data": {
        "groupId": "{{group_id}}",
        "content": "Hello everyone! 👋",
        "messageType": "text",
        "metadata": {}
      }
    },
    "send_reply_message": {
      "event": "sendGroupMessage",
      "data": {
        "groupId": "{{group_id}}",
        "content": "This is a reply to your message",
        "messageType": "text",
        "replyToMessageId": "previous-message-id",
        "metadata": {}
      }
    },
    "typing_indicator": {
      "event": "groupTyping",
      "data": {
        "groupId": "{{group_id}}",
        "isTyping": true
      }
    },
    "stop_typing": {
      "event": "groupTyping",
      "data": {
        "groupId": "{{group_id}}",
        "isTyping": false
      }
    },
    "get_message_history": {
      "event": "getGroupMessageHistory",
      "data": {
        "groupId": "{{group_id}}",
        "page": 1,
        "limit": 50
      }
    },
    "mark_as_read": {
      "event": "markGroupMessageAsRead",
      "data": {
        "groupId": "{{group_id}}",
        "messageIds": ["message-id-1", "message-id-2"]
      }
    },
    "delete_message": {
      "event": "deleteGroupMessage",
      "data": {
        "groupId": "{{group_id}}",
        "messageId": "message-to-delete-id"
      }
    },
    "edit_message": {
      "event": "editGroupMessage",
      "data": {
        "groupId": "{{group_id}}",
        "messageId": "message-to-edit-id",
        "newContent": "This message has been edited!"
      }
    },
    "get_group_members": {
      "event": "getGroupMembers",
      "data": {
        "groupId": "{{group_id}}"
      }
    },
    "leave_group": {
      "event": "leaveGroup",
      "data": {
        "groupId": "{{group_id}}"
      }
    }
  },
  "expected_responses": {
    "authentication_success": {
      "event": "authenticated",
      "data": {
        "success": true,
        "userId": "user-uuid",
        "userName": "User Name"
      }
    },
    "message_received": {
      "event": "groupMessageReceived",
      "data": {
        "messageId": "message-id",
        "senderId": "sender-uuid",
        "senderName": "Sender Name",
        "senderAvatarUrl": "avatar-url",
        "groupId": "group-uuid",
        "content": "Message content",
        "messageType": "text",
        "metadata": {},
        "timestamp": "2023-10-01T12:00:00Z",
        "readBy": ["sender-uuid"],
        "deliveredTo": []
      }
    },
    "user_joined": {
      "event": "userJoinedGroup",
      "data": {
        "userId": "user-uuid",
        "userName": "User Name",
        "groupId": "group-uuid"
      }
    },
    "typing_indicator": {
      "event": "userTypingInGroup",
      "data": {
        "groupId": "group-uuid",
        "userId": "user-uuid",
        "userName": "User Name",
        "isTyping": true
      }
    }
  }
}

{
  "scenario": "Multi-User Group Testing",
  "description": "Test group chat with multiple users, permissions, and advanced features",
  "prerequisites": [
    "Multiple test users registered",
    "Basic group chat flow completed successfully",
    "Group with proper roles and permissions set up"
  ],
  "steps": [
    {
      "step": 1,
      "description": "Test Group Permissions",
      "action": "Verify role-based permissions",
      "sub_steps": [
        "Test message deletion by non-admin (should fail)",
        "Test message deletion by admin (should succeed)",
        "Test member management permissions"
      ]
    },
    {
      "step": 2,
      "description": "Test Message Broadcasting",
      "action": "Send message from one user, verify all receive",
      "sub_steps": [
        "User A sends message",
        "Verify Users B, C, D all receive message",
        "Check message delivery and read status"
      ]
    },
    {
      "step": 3,
      "description": "Test User Join/Leave Events",
      "action": "Test real-time user presence",
      "sub_steps": [
        "User joins group - all should receive userJoinedGroup",
        "User leaves group - all should receive userLeftGroup",
        "Test connection/disconnection handling"
      ]
    },
    {
      "step": 4,
      "description": "Test Concurrent Messaging",
      "action": "Multiple users send messages simultaneously",
      "expected": "All messages delivered in correct order"
    },
    {
      "step": 5,
      "description": "Test Message History Pagination",
      "action": "Send 100+ messages, test pagination",
      "sub_steps": [
        "Send bulk messages",
        "Test page-by-page retrieval",
        "Test 'before' parameter for cursor-based pagination"
      ]
    }
  ]
}
